const tabId = 2052873279;
const cardStructure = await browserjs(tabId, () => {
  const headings = Array.from(document.querySelectorAll('h3, h4, [role="heading"]'));
  const chicken = headings.find(h => h.innerText.includes('Chicken Breasts'));
  if (!chicken) return "not found";
  let parent = chicken;
  const chain = [];
  for (let i = 0; i < 6; i++) {
    parent = parent.parentElement;
    if (parent) {
      chain.push({
        tag: parent.tagName,
        className: parent.className,
        role: parent.getAttribute('role'),
        links: Array.from(parent.querySelectorAll('a')).map(a => a.href),
        buttons: Array.from(parent.querySelectorAll('button')).map(b => b.innerText.trim() || b.getAttribute('aria-label'))
      });
    }
  }
  return chain;
});
