const tabId = 2052873279;
const info = await browserjs(tabId, () => {
  const elements = Array.from(document.querySelectorAll('*'));
  const target = elements.find(el => el.children.length === 0 && el.innerText?.includes('Publix Boneless Skinless Chicken Breasts'));
  if (!target) return { found: false };
  let curr = target;
  const path = [];
  while (curr && curr !== document.body) {
    path.push({
      tag: curr.tagName,
      class: curr.className,
      id: curr.id,
      role: curr.getAttribute('role'),
      ariaLabel: curr.getAttribute('aria-label')
    });
    curr = curr.parentElement;
  }
  return { found: true, text: target.innerText, path };
});
