const tabId = 2052873279;
const bogoDeals = await browserjs(tabId, () => {
  // Let's find all product cards or items
  const cards = Array.from(document.querySelectorAll('[data-qa*="item"], .p-card, article, [class*="card"]'));
  // Or let's grab all text elements mentioning "Buy 1 Get 1 Free"
  const elements = Array.from(document.querySelectorAll('*'));
  const bogoContainers = [];
  for (const el of elements) {
    if (el.children.length === 0 && el.innerText?.trim() === 'Buy 1 Get 1 Free') {
      let parent = el.parentElement;
      for (let i = 0; i < 5; i++) {
        if (parent && parent.innerText.length > 20 && parent.innerText.length < 500) {
          bogoContainers.push(parent.innerText);
          break;
        }
        parent = parent?.parentElement;
      }
