const tabId = 2052873279;
const items = await browserjs(tabId, () => {
  // Find all cards
  const results = [];
  const elements = Array.from(document.querySelectorAll('*'));
  for (const el of elements) {
    if (el.children.length === 0 && el.innerText?.trim() === 'Buy 1 Get 1 Free') {
      let card = el;
      for (let i = 0; i < 6; i++) {
        if (card.parentElement && card.parentElement.innerText.includes('Add to list')) {
          card = card.parentElement;
          break;
        }
        card = card.parentElement;
      }
      if (card) {
        const text = card.innerText.trim();
        const link = card.querySelector('a')?.href || null;
        const title = card.querySelector('h2, h3, h4, [class*="title"], strong')?.innerText || text.split('\n')[0];
        results.push({ title, text, link });
      }
    }
  }
  // Remove duplicates by title
  const unique = [];
  const seen = new Set();
  for (const r of results) {
    if (!seen.has(r.title)) {
      seen.add(r.title);
      unique.push(r);
    }
  }
  return unique;
});

