  const elements = Array.from(document.querySelectorAll('*'));
  const target = elements.find(el => el.children.length === 0 && el.innerText?.includes('Publix Boneless Skinless Chicken Breasts'));
  if (!target) return { found: false };
  let curr = target;
  const path = [];
  while (curr && curr !== document.body) {
