      tag: curr.tagName,
      class: curr.className,
      id: curr.id,
      role: curr.getAttribute('role'),
      ariaLabel: curr.getAttribute('aria-label')
    });
    curr = curr.parentElement;
  }
  return { found: true, text: target.innerText, path };
});
