const sections = await browserjs(tabId, () => {
  const tabs = Array.from(document.querySelectorAll('a, button')).filter(el => {
    const t = el.innerText.trim();
    return t === 'DIGESTIFS' || t === 'SPIRIT FREE' || t === 'APÉRITIFS';
  });
  return tabs.map(t => ({ text: t.innerText, href: t.href, tag: t.tagName }));
});
console.log("Sections:", sections);

